require "test_helper"

class DebugTest < ActiveSupport::TestCase
  def sql_counter
    count = { total: 0, insert: 0 }
    handler = ->(_name, _started, _finished, _id, payload) {
      sql = payload[:sql]
      count[:total] += 1
      count[:insert] += 1 if sql =~ /\A\s*INSERT/i
    }
    ActiveSupport::Notifications.subscribed(handler, "sql.active_record") { yield }
    count
  end

  def build_grants(b)
    users = 16.times.map { |i| User.create!(name: "U#{i}", email_address: "u#{i}@example.com", password: "secret123456") }
    grants = users.map { |u| { user_id: u.id, level: "reader" } }
    grants # david not included
  end

  def test_it
    b4 = Book.create!(title: "B4", everyone_access: false)
    g4 = 4.times.map { |i| { user_id: User.create!(name: "a#{i}", email_address: "a#{i}@example.com", password: "x").id, level: "reader" } }
    cnt4 = sql_counter { Book::AccessImport.new(b4, g4).import }

    b16 = Book.create!(title: "B16", everyone_access: false)
    g16 = 16.times.map { |i| { user_id: User.create!(name: "b#{i}", email_address: "b#{i}@example.com", password: "x").id, level: "reader" } }
    cnt16 = sql_counter { Book::AccessImport.new(b16, g16).import }

    puts "4 grants:  total=#{cnt4[:total]} insert=#{cnt4[:insert]}"
    puts "16 grants: total=#{cnt16[:total]} insert=#{cnt16[:insert]}"

    # turned down via duplicate at end (david already on manual)
    bD = Book.create!(title: "BD", everyone_access: false)
    gD = 16.times.map { |i| { user_id: User.create!(name: "c#{i}", email_address: "c#{i}@example.com", password: "x").id, level: "reader" } }
    gD << { user_id: users(:david).id, level: "reader" }
    cntD = sql_counter { Book::AccessImport.new(bD, gD).import }
    puts "16 + dup turned down: total=#{cntD[:total]} insert=#{cntD[:insert]}"
  end
end
